const state={config:null,sessions:[],activeSession:null,messages:[],models:[],busy:false,statuses:{},benchmarkCases:[],benchmarkRuns:[],activeCase:null,activeRun:null,pollTimer:null};
const $=(selector,root=document)=>root.querySelector(selector);
const $$=(selector,root=document)=>[...root.querySelectorAll(selector)];

async function api(path,options={}){const response=await fetch(`/api${path}`,{headers:{"Content-Type":"application/json",...(options.headers||{})},...options});if(response.status===204)return null;const data=await response.json().catch(()=>({error:`HTTP ${response.status}`}));if(!response.ok)throw new Error(data.error||`HTTP ${response.status}`);return data}
function escapeHTML(value=""){return String(value).replace(/[&<>'"]/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[char]))}
function formatDuration(ms){if(ms==null)return"—";return ms<1000?`${ms} ms`:`${(ms/1000).toFixed(2)} s`}
function toast(message,type="success"){const item=document.createElement("div");item.className=`toast ${type}`;item.textContent=message;$("#toast-region").append(item);setTimeout(()=>item.remove(),4200)}
function setBusy(value){state.busy=value;$("#send-button").disabled=value;$("#send-button").innerHTML=value?'<span class="spinner"></span> Running…':'Send <span>↑</span>'}

async function bootstrap(){try{await api("/health");$("#runtime-status").textContent="Connected";state.config=await api("/config");await Promise.all([loadSessions(),loadBenchmarks()]);renderAll()}catch(error){$("#runtime-status").textContent="Unavailable";toast(error.message,"error")}}
function renderAll(){renderProviderSelect();renderMCPPicker();renderConnections();renderSessions();renderMessages();renderInspector();renderBenchmarks();$("#runner-max-steps").value=state.config.runner.max_steps;$("#runner-parallel").value=state.config.runner.parallel_runs}

function switchView(name){$$('.nav-item').forEach(item=>item.classList.toggle("active",item.dataset.view===name));$$('.view').forEach(item=>item.classList.toggle("active",item.id===`${name}-view`));const titles={chat:["MODEL WORKSPACE","Chat laboratory"],connections:["RUNTIME CONTROL","Connections"],benchmarks:["EXPERIMENTS","Benchmarks"]};$("#view-eyebrow").textContent=titles[name][0];$("#view-title").textContent=titles[name][1]}

function renderProviderSelect(){const enabled=state.config.providers.filter(item=>item.enabled);const select=$("#chat-provider");const current=select.value||state.activeSession?.provider_id||enabled[0]?.id||"";select.innerHTML=enabled.map(item=>`<option value="${escapeHTML(item.id)}">${escapeHTML(item.name)}</option>`).join("");select.value=enabled.some(item=>item.id===current)?current:(enabled[0]?.id||"");const selected=enabled.find(item=>item.id===select.value);if(!$("#chat-model").value)$("#chat-model").value=state.activeSession?.model||selected?.default_model||""}
function renderMCPPicker(){const selected=new Set(state.activeSession?.mcp_server_ids||[]);const enabled=state.config.mcp_servers.filter(item=>item.enabled);$("#mcp-picker").innerHTML=enabled.length?enabled.map(item=>`<label class="mcp-chip"><input type="checkbox" value="${escapeHTML(item.id)}" ${selected.has(item.id)?"checked":""}>${escapeHTML(item.name)}</label>`).join(""):'<span class="mcp-chip">No MCP servers configured</span>'}

function renderConnections(){const providers=state.config.providers,mcpServers=state.config.mcp_servers;$("#provider-count").textContent=providers.length;$("#mcp-count").textContent=mcpServers.length;$("#provider-grid").innerHTML=providers.length?providers.map(providerCard).join(""):emptyConnection("No providers yet","Add OpenRouter, Gemini, or a local OpenAI-compatible endpoint.");$("#mcp-grid").innerHTML=mcpServers.length?mcpServers.map(mcpCard).join(""):emptyConnection("No MCP servers yet","Connect SkillBox, RagBox, or any Streamable HTTP MCP server.");$$('[data-action="edit-provider"]').forEach(button=>button.onclick=()=>openConnection("provider",button.dataset.id));$$('[data-action="edit-mcp"]').forEach(button=>button.onclick=()=>openConnection("mcp",button.dataset.id));$$('[data-action="test-provider"]').forEach(button=>button.onclick=()=>testConnection("provider",button));$$('[data-action="test-mcp"]').forEach(button=>button.onclick=()=>testConnection("mcp",button))}
function providerCard(item){const status=state.statuses[`provider:${item.id}`]||{state:item.enabled?"enabled":"disabled",label:item.enabled?"Ready":"Disabled"};return `<article class="connection-card"><div class="card-top"><div class="connection-identity"><div class="connection-icon">◌</div><div><h3>${escapeHTML(item.name)}</h3><p>${escapeHTML(item.base_url)}</p></div></div><span class="connection-status ${status.state}"><i></i>${escapeHTML(status.label)}</span></div><div class="connection-meta"><div><span>Type</span><strong>OpenAI compatible</strong></div><div><span>Secret</span><strong>${item.api_key_configured?"Configured":"Not configured"}</strong></div><div><span>Default model</span><strong>${escapeHTML(item.default_model||"Not selected")}</strong></div><div><span>Timeout</span><strong>${escapeHTML(item.request_timeout||"120s")}</strong></div></div><div class="card-actions"><button class="secondary-button" data-action="test-provider" data-id="${escapeHTML(item.id)}">Test</button><button class="secondary-button" data-action="edit-provider" data-id="${escapeHTML(item.id)}">Configure</button></div></article>`}
function mcpCard(item){const status=state.statuses[`mcp:${item.id}`]||{state:item.enabled?"enabled":"disabled",label:item.enabled?"Ready":"Disabled"};return `<article class="connection-card"><div class="card-top"><div class="connection-identity"><div class="connection-icon">⌁</div><div><h3>${escapeHTML(item.name)}</h3><p>${escapeHTML(item.url)}</p></div></div><span class="connection-status ${status.state}"><i></i>${escapeHTML(status.label)}</span></div><div class="connection-meta"><div><span>Transport</span><strong>Streamable HTTP</strong></div><div><span>Authorization</span><strong>${item.auth_value_configured?"Configured":"Not configured"}</strong></div><div><span>Environment</span><strong>${escapeHTML(item.auth_value_env||"Inline / none")}</strong></div><div><span>Timeout</span><strong>${escapeHTML(item.request_timeout||"30s")}</strong></div></div><div class="card-actions"><button class="secondary-button" data-action="test-mcp" data-id="${escapeHTML(item.id)}">Test & tools</button><button class="secondary-button" data-action="edit-mcp" data-id="${escapeHTML(item.id)}">Configure</button></div></article>`}
function emptyConnection(title,description){return `<article class="connection-card"><h3>${title}</h3><p>${description}</p></article>`}

async function testConnection(kind,button){const id=button.dataset.id;const key=`${kind}:${id}`;button.disabled=true;button.innerHTML='<span class="spinner"></span> Testing';try{const result=await api(kind==="provider"?`/providers/${encodeURIComponent(id)}/test`:`/mcp/${encodeURIComponent(id)}/test`,{method:"POST"});state.statuses[key]={state:"connected",label:kind==="provider"?`${result.models} models`:`${result.tools.length} tools`};toast(kind==="provider"?`Connected · ${result.models} models`:`Connected · ${result.tools.length} tools`)}catch(error){state.statuses[key]={state:"failed",label:"Failed"};toast(error.message,"error")}finally{renderConnections()}}
async function loadModels(){const id=$("#chat-provider").value;if(!id)return toast("Select a provider first","error");const button=$("#load-models");button.disabled=true;button.innerHTML='<span class="spinner"></span>';try{const result=await api(`/providers/${encodeURIComponent(id)}/models`);state.models=result.models;$("#model-options").innerHTML=result.models.map(item=>`<option value="${escapeHTML(item.id)}">${escapeHTML(item.name||item.id)}</option>`).join("");toast(`Loaded ${result.models.length} models`)}catch(error){toast(error.message,"error")}finally{button.disabled=false;button.textContent="↻"}}

async function loadSessions(){const result=await api("/sessions");state.sessions=result.sessions||[]}
function renderSessions(){$("#session-list").innerHTML=state.sessions.map(item=>`<button class="session-item ${state.activeSession?.id===item.id?"active":""}" data-session="${escapeHTML(item.id)}">${escapeHTML(item.title)}</button>`).join("");$$('[data-session]').forEach(button=>button.onclick=()=>openSession(button.dataset.session))}
async function openSession(id){try{const result=await api(`/sessions/${encodeURIComponent(id)}`);state.activeSession=result.session;state.messages=result.messages||[];$("#chat-provider").value=state.activeSession.provider_id;$("#chat-model").value=state.activeSession.model;$("#chat-mode").value=state.activeSession.mode||"no_skill";renderProviderSelect();renderMCPPicker();renderSessions();renderMessages();renderInspector();switchView("chat")}catch(error){toast(error.message,"error")}}
function newChat(){state.activeSession=null;state.messages=[];$("#message-input").value="";renderMCPPicker();renderSessions();renderMessages();renderInspector();switchView("chat")}
function renderMessages(){const container=$("#messages");if(!state.messages.length){container.innerHTML='<div class="empty-chat"><div class="empty-icon">✦</div><h2>Compare ideas before benchmarks</h2><p>Select a model, attach MCP servers, and inspect every tool call. Conversations are stored only in the Benchmark SQLite database.</p></div>';return}container.innerHTML=state.messages.map(item=>`<article class="message ${item.role}"><div class="message-avatar">${item.role==="assistant"?"✦":"U"}</div><div class="message-body"><div class="message-meta"><strong>${item.role==="assistant"?escapeHTML(item.model||"Assistant"):"You"}</strong><span>${new Date(item.created_at).toLocaleString()}</span></div><div class="message-content">${escapeHTML(item.content)}</div>${item.role==="assistant"?`<div class="message-stats"><span>${formatDuration(item.duration_ms)}</span><span>${item.input_tokens??0} in</span><span>${item.output_tokens??0} out</span><span>${item.tool_calls_count||0} tools</span></div>`:""}</div></article>`).join("");container.scrollTop=container.scrollHeight}
function renderInspector(){const assistant=[...state.messages].reverse().find(item=>item.role==="assistant");if(!assistant){$("#inspector-content").innerHTML='<div class="inspector-empty"><span>⌁</span><p>Run a message to see latency, tokens, and MCP tool activity.</p></div>';return}const calls=assistant.tool_calls||[];$("#inspector-content").innerHTML=`<div class="metric-grid"><div class="metric"><span>Latency</span><strong>${formatDuration(assistant.duration_ms)}</strong></div><div class="metric"><span>Tool calls</span><strong>${assistant.tool_calls_count||0}</strong></div><div class="metric"><span>Input tokens</span><strong>${assistant.input_tokens??0}</strong></div><div class="metric"><span>Output tokens</span><strong>${assistant.output_tokens??0}</strong></div></div><div class="tool-section"><h3>MCP trajectory</h3>${calls.length?calls.map((call,index)=>`<details class="tool-card"><summary>${index+1}. ${escapeHTML(call.server_id)} · ${escapeHTML(call.tool_name)} · ${formatDuration(call.duration_ms)}</summary><pre>Arguments\n${escapeHTML(call.arguments)}\n\n${call.error?`Error\n${escapeHTML(call.error)}`:`Result\n${escapeHTML(call.result)}`}</pre></details>`).join(""):'<div class="inspector-empty"><p>No tools were called in this response.</p></div>'}</div>`}

async function sendMessage(event){event.preventDefault();if(state.busy)return;const message=$("#message-input").value.trim(),providerId=$("#chat-provider").value,model=$("#chat-model").value.trim();if(!message||!providerId||!model)return toast("Select a provider and model, then enter a message","error");const mcpIds=$$('#mcp-picker input:checked').map(item=>item.value);setBusy(true);$("#message-input").value="";const optimistic={id:`local-${Date.now()}`,role:"user",content:message,created_at:new Date().toISOString()};state.messages.push(optimistic);renderMessages();try{const result=await api("/chat",{method:"POST",body:JSON.stringify({session_id:state.activeSession?.id||"",provider_id:providerId,model,mcp_server_ids:mcpIds,mode:$("#chat-mode").value,message})});state.activeSession=result.session;const loaded=await api(`/sessions/${encodeURIComponent(result.session.id)}`);state.activeSession=loaded.session;state.messages=loaded.messages;await loadSessions();renderAll()}catch(error){state.messages=state.messages.filter(item=>item.id!==optimistic.id);renderMessages();toast(error.message,"error")}finally{setBusy(false);$("#message-input").focus()}}

function openConnection(kind,id=""){const editing=Boolean(id);const item=kind==="provider"?state.config.providers.find(value=>value.id===id):state.config.mcp_servers.find(value=>value.id===id);$("#dialog-title").textContent=editing?`Configure ${item.name}`:"Add connection";$("#connection-original-id").value=id;$("#connection-kind").value=kind;$("#connection-kind").disabled=editing;$("#connection-id").value=item?.id||"";$("#connection-id").disabled=editing;$("#connection-name").value=item?.name||"";$("#connection-url").value=item?.base_url||item?.url||"";$("#connection-timeout").value=item?.request_timeout||(kind==="provider"?"120s":"30s");$("#connection-enabled").checked=item?.enabled??true;$("#provider-model").value=item?.default_model||"";$("#provider-key-env").value=item?.api_key_env||"";$("#provider-key").value="";$("#mcp-auth-header").value=item?.auth_header||"Authorization";$("#mcp-auth-env").value=item?.auth_value_env||"";$("#mcp-auth-value").value="";$("#delete-connection").hidden=!editing;toggleConnectionFields();$("#connection-dialog").showModal()}
function toggleConnectionFields(){const provider=$("#connection-kind").value==="provider";$("#provider-fields").hidden=!provider;$("#mcp-fields").hidden=provider}
async function saveConnection(event){event.preventDefault();const kind=$("#connection-kind").value,id=$("#connection-id").value.trim(),original=$("#connection-original-id").value;const common={id,name:$("#connection-name").value.trim(),enabled:$("#connection-enabled").checked,request_timeout:$("#connection-timeout").value.trim()};if(kind==="provider"){const previous=state.config.providers.find(item=>item.id===original);const next={...common,type:"openai_compatible",base_url:$("#connection-url").value.trim(),api_key:$("#provider-key").value||"",api_key_configured:Boolean($("#provider-key").value)||previous?.api_key_configured||false,api_key_env:$("#provider-key-env").value.trim(),default_model:$("#provider-model").value.trim()};state.config.providers=state.config.providers.filter(item=>item.id!==original);state.config.providers.push(next)}else{const previous=state.config.mcp_servers.find(item=>item.id===original);const next={...common,transport:"streamable_http",url:$("#connection-url").value.trim(),auth_header:$("#mcp-auth-header").value.trim(),auth_value:$("#mcp-auth-value").value||"",auth_value_configured:Boolean($("#mcp-auth-value").value)||previous?.auth_value_configured||false,auth_value_env:$("#mcp-auth-env").value.trim()};state.config.mcp_servers=state.config.mcp_servers.filter(item=>item.id!==original);state.config.mcp_servers.push(next)}try{await persistConfig();$("#connection-dialog").close();toast("Connection saved and applied") }catch(error){toast(error.message,"error")}}
async function persistConfig(){const result=await api("/config",{method:"PUT",body:JSON.stringify(state.config)});state.config=result.config;renderAll();if(result.restart_required)toast("Saved. Server address or database path requires restart.")}
async function removeConnection(){const kind=$("#connection-kind").value,id=$("#connection-original-id").value;if(!id||!confirm(`Remove connection “${id}”? Existing chat history will be preserved.`))return;if(kind==="provider")state.config.providers=state.config.providers.filter(item=>item.id!==id);else state.config.mcp_servers=state.config.mcp_servers.filter(item=>item.id!==id);try{await persistConfig();$("#connection-dialog").close();toast("Connection removed") }catch(error){toast(error.message,"error")}}

async function loadBenchmarks(){const [caseResult,runResult]=await Promise.all([api("/benchmarks/cases"),api("/benchmarks/runs")]);state.benchmarkCases=caseResult.cases||[];state.benchmarkRuns=runResult.runs||[];if(state.activeCase)state.activeCase=state.benchmarkCases.find(item=>item.id===state.activeCase.id)||null;if(state.activeRun)state.activeRun=state.benchmarkRuns.find(item=>item.id===state.activeRun.id)||null}
function renderBenchmarks(){if(!state.config)return;$("#case-count").textContent=state.benchmarkCases.length;$("#benchmark-case-list").innerHTML=state.benchmarkCases.length?state.benchmarkCases.map(item=>`<button class="benchmark-case ${state.activeCase?.id===item.id?"active":""}" data-benchmark-case="${escapeHTML(item.id)}"><h3>${escapeHTML(item.name)}</h3><p>${escapeHTML(item.task)}</p><div class="benchmark-case-meta"><span>${item.targets.length} models</span><span>${item.repetitions}× paired</span></div></button>`).join(""):'<div class="benchmark-empty"><p>No cases yet.</p></div>';$$('[data-benchmark-case]').forEach(button=>button.onclick=()=>selectBenchmarkCase(button.dataset.benchmarkCase));renderBenchmarkResult()}
function selectBenchmarkCase(id){state.activeCase=state.benchmarkCases.find(item=>item.id===id)||null;state.activeRun=state.benchmarkRuns.find(item=>item.case_id===id)||null;renderBenchmarks()}
function renderBenchmarkResult(){const container=$("#benchmark-result-content"),item=state.activeCase;if(!item){container.innerHTML='<div class="benchmark-empty"><span>◇</span><h2>No benchmark selected</h2><p>Create a case with model targets, a published Skill, task MCP servers, and deterministic grading rules.</p></div>';return}const run=state.activeRun;container.innerHTML=`<div class="benchmark-head"><div><span class="eyebrow">PAIRED CASE</span><h2>${escapeHTML(item.name)}</h2><p>${escapeHTML(item.description||item.task)}</p></div><div class="benchmark-actions"><button class="secondary-button" id="edit-active-case">Configure</button><button class="primary-button" id="run-active-case" ${run&&["queued","running"].includes(run.status)?"disabled":""}>${run&&["queued","running"].includes(run.status)?"Running…":"▶ Run paired test"}</button></div></div>${run?renderRun(run):'<div class="benchmark-empty"><span>◇</span><h2>Ready to run</h2><p>${item.targets.length*item.repetitions*2} trials will compare Baseline and With Skill using the same tasks, model parameters, and MCP tools.</p></div>'}`;$("#edit-active-case").onclick=()=>openBenchmarkDialog(item.id);$("#run-active-case").onclick=()=>startBenchmark(item.id);$$('[data-run-id]').forEach(button=>button.onclick=()=>openBenchmarkRun(button.dataset.runId))}
function renderRun(run){const progress=run.total_trials?Math.round(run.completed_trials/run.total_trials*100):0;const summaries=summarizeRun(run);const all=run.trials||[],baseline=all.filter(item=>item.variant==="baseline"),skill=all.filter(item=>item.variant==="with_skill"),avgBaseline=average(baseline,"quality_score"),avgSkill=average(skill,"quality_score"),improvement=avgSkill-avgBaseline;return `<div class="run-progress"><div class="run-progress-head"><span>${escapeHTML(run.status)} · ${run.completed_trials}/${run.total_trials} trials</span><span>${progress}%</span></div><div class="progress-track"><i style="width:${progress}%"></i></div>${run.error?`<p class="fail">${escapeHTML(run.error)}</p>`:""}</div><div class="summary-grid"><div class="summary-card"><span>Baseline quality</span><strong>${avgBaseline.toFixed(1)}</strong></div><div class="summary-card"><span>With Skill quality</span><strong>${avgSkill.toFixed(1)}</strong></div><div class="summary-card"><span>Improvement</span><strong class="${improvement>=0?"positive":"fail"}">${improvement>=0?"+":""}${improvement.toFixed(1)}</strong></div><div class="summary-card"><span>Paired trials</span><strong>${Math.min(baseline.length,skill.length)}</strong></div></div><div class="comparison-list">${summaries.map(renderComparison).join("")}</div>${renderTrialTable(all)}`}
function summarizeRun(run){const groups=new Map;for(const trial of run.trials||[]){const key=`${trial.provider_id}\n${trial.model}`;if(!groups.has(key))groups.set(key,{provider:trial.provider_id,model:trial.model,baseline:[],skill:[]});groups.get(key)[trial.variant==="baseline"?"baseline":"skill"].push(trial)}return [...groups.values()]}
function average(items,field){return items.length?items.reduce((sum,item)=>sum+Number(item[field]||0),0)/items.length:0}
function passRate(items){return items.length?items.filter(item=>item.passed).length/items.length*100:0}
function renderComparison(group){const base=average(group.baseline,"quality_score"),skill=average(group.skill,"quality_score"),delta=skill-base;return `<article class="comparison-card"><div class="comparison-title"><h3>${escapeHTML(group.model)}</h3><span>${escapeHTML(group.provider)} · Δ ${delta>=0?"+":""}${delta.toFixed(1)}</span></div><div class="bar-pair"><div class="score-bar baseline"><span>Baseline</span><div class="score-track"><i style="width:${Math.max(0,Math.min(100,base))}%"></i></div><strong>${base.toFixed(1)}</strong></div><div class="score-bar skill"><span>With Skill</span><div class="score-track"><i style="width:${Math.max(0,Math.min(100,skill))}%"></i></div><strong>${skill.toFixed(1)}</strong></div></div><div class="comparison-metrics"><div><span>Pass baseline</span><strong>${passRate(group.baseline).toFixed(0)}%</strong></div><div><span>Pass with Skill</span><strong>${passRate(group.skill).toFixed(0)}%</strong></div><div><span>Time baseline</span><strong>${formatDuration(average(group.baseline,"duration_ms"))}</strong></div><div><span>Time with Skill</span><strong>${formatDuration(average(group.skill,"duration_ms"))}</strong></div></div></article>`}
function renderTrialTable(trials){if(!trials.length)return"";return `<div class="trial-table-wrap"><table class="trial-table"><thead><tr><th>Model</th><th>Variant</th><th>Repeat</th><th>Quality</th><th>Pass</th><th>Duration</th><th>Tokens</th><th>Tools</th></tr></thead><tbody>${trials.map(item=>`<tr title="${escapeHTML(item.error||item.response)}"><td>${escapeHTML(item.model)}</td><td>${item.variant==="with_skill"?"With Skill":"Baseline"}</td><td>${item.repetition}</td><td>${Number(item.quality_score).toFixed(1)}</td><td class="${item.passed?"pass":"fail"}">${item.passed?"Passed":"Failed"}</td><td>${formatDuration(item.duration_ms)}</td><td>${item.input_tokens+item.output_tokens}</td><td>${item.tool_calls_count}</td></tr>`).join("")}</tbody></table></div>`}
async function openBenchmarkRun(id){try{state.activeRun=await api(`/benchmarks/runs/${encodeURIComponent(id)}`);state.activeCase=state.benchmarkCases.find(item=>item.id===state.activeRun.case_id)||state.activeCase;renderBenchmarks()}catch(error){toast(error.message,"error")}}
async function startBenchmark(caseId){try{state.activeRun=await api(`/benchmarks/cases/${encodeURIComponent(caseId)}/runs`,{method:"POST"});toast(`Started ${state.activeRun.total_trials} paired trials`);renderBenchmarks();pollBenchmarkRun(state.activeRun.id)}catch(error){toast(error.message,"error")}}
function pollBenchmarkRun(id){clearTimeout(state.pollTimer);state.pollTimer=setTimeout(async()=>{try{const run=await api(`/benchmarks/runs/${encodeURIComponent(id)}`);state.activeRun=run;const index=state.benchmarkRuns.findIndex(item=>item.id===run.id);if(index>=0)state.benchmarkRuns[index]=run;else state.benchmarkRuns.unshift(run);renderBenchmarks();if(["queued","running"].includes(run.status))pollBenchmarkRun(id);else toast(`Benchmark ${run.status}`)}catch(error){toast(error.message,"error")}},900)}

function openBenchmarkDialog(id=""){const item=state.benchmarkCases.find(value=>value.id===id);$("#benchmark-dialog-title").textContent=item?`Configure ${item.name}`:"New benchmark";$("#benchmark-id").value=item?.id||"";$("#benchmark-name").value=item?.name||"";$("#benchmark-description").value=item?.description||"";$("#benchmark-task").value=item?.task||"";$("#benchmark-skill-id").value=item?.skill_id||"";$("#benchmark-repetitions").value=item?.repetitions||3;$("#benchmark-max-tokens").value=item?.max_tokens||2048;$("#benchmark-required-phrases").value=(item?.required_phrases||[]).join("\n");$("#benchmark-forbidden-phrases").value=(item?.forbidden_phrases||[]).join("\n");$("#benchmark-required-tools").value=(item?.required_tools||[]).join("\n");const servers=state.config.mcp_servers.filter(value=>value.enabled);$("#benchmark-skill-server").innerHTML=servers.map(value=>`<option value="${escapeHTML(value.id)}">${escapeHTML(value.name)}</option>`).join("");$("#benchmark-skill-server").value=item?.skill_mcp_server_id||servers.find(value=>value.id.includes("skillbox"))?.id||servers[0]?.id||"";const selected=new Set(item?.mcp_server_ids||[]);$("#benchmark-mcp-picker").innerHTML=servers.map(value=>`<label><input type="checkbox" value="${escapeHTML(value.id)}" ${selected.has(value.id)?"checked":""}>${escapeHTML(value.name)}</label>`).join("")||"No enabled MCP servers";$("#benchmark-targets").innerHTML="";for(const target of item?.targets||[{provider_id:state.config.providers.find(value=>value.enabled)?.id||"",model:""}])addBenchmarkTarget(target);$("#benchmark-dialog").showModal()}
function addBenchmarkTarget(target={}){const row=document.createElement("div");row.className="target-row";row.innerHTML=`<select class="target-provider">${state.config.providers.filter(item=>item.enabled).map(item=>`<option value="${escapeHTML(item.id)}" ${item.id===target.provider_id?"selected":""}>${escapeHTML(item.name)}</option>`).join("")}</select><input class="target-model" required placeholder="Exact model ID" value="${escapeHTML(target.model||"")}"><button type="button" class="icon-button" title="Remove model">×</button>`;row.querySelector("button").onclick=()=>row.remove();$("#benchmark-targets").append(row)}
function excludeSkillServerFromTaskTools(){const selected=$("#benchmark-skill-server").value;const checkbox=$(`#benchmark-mcp-picker input[value="${CSS.escape(selected)}"]`);if(checkbox)checkbox.checked=false}
function lines(value){return value.split("\n").map(item=>item.trim()).filter(Boolean)}
async function saveBenchmark(event){event.preventDefault();const targets=$$('#benchmark-targets .target-row').map(row=>({provider_id:$('.target-provider',row).value,model:$('.target-model',row).value.trim()}));const item={id:$("#benchmark-id").value,name:$("#benchmark-name").value.trim(),description:$("#benchmark-description").value.trim(),task:$("#benchmark-task").value.trim(),mcp_server_ids:$$('#benchmark-mcp-picker input:checked').map(input=>input.value),skill_mcp_server_id:$("#benchmark-skill-server").value,skill_id:$("#benchmark-skill-id").value.trim(),repetitions:Number($("#benchmark-repetitions").value),max_tokens:Number($("#benchmark-max-tokens").value),required_phrases:lines($("#benchmark-required-phrases").value),forbidden_phrases:lines($("#benchmark-forbidden-phrases").value),required_tools:lines($("#benchmark-required-tools").value),targets};try{const saved=await api("/benchmarks/cases",{method:"POST",body:JSON.stringify(item)});$("#benchmark-dialog").close();await loadBenchmarks();state.activeCase=state.benchmarkCases.find(value=>value.id===saved.id);state.activeRun=state.benchmarkRuns.find(value=>value.case_id===saved.id)||null;renderBenchmarks();toast("Benchmark case saved")}catch(error){toast(error.message,"error")}}

$$('.nav-item').forEach(item=>item.onclick=()=>switchView(item.dataset.view));$("#composer").onsubmit=sendMessage;$("#message-input").onkeydown=event=>{if(event.key==="Enter"&&!event.shiftKey){event.preventDefault();$("#composer").requestSubmit()}};$("#load-models").onclick=loadModels;$("#chat-provider").onchange=()=>{const selected=state.config.providers.find(item=>item.id===$("#chat-provider").value);$("#chat-model").value=selected?.default_model||"";state.models=[];$("#model-options").innerHTML=""};$("#new-chat").onclick=newChat;$("#new-chat-small").onclick=newChat;$("#add-connection").onclick=()=>openConnection("provider");$("#connection-kind").onchange=toggleConnectionFields;$("#connection-form").onsubmit=saveConnection;$("#close-dialog").onclick=()=>$("#connection-dialog").close();$("#cancel-dialog").onclick=()=>$("#connection-dialog").close();$("#delete-connection").onclick=removeConnection;$("#save-runtime").onclick=async()=>{state.config.runner.max_steps=Number($("#runner-max-steps").value);state.config.runner.parallel_runs=Number($("#runner-parallel").value);try{await persistConfig();toast("Runner settings applied")}catch(error){toast(error.message,"error")}};$("#reload-config").onclick=async()=>{try{const result=await api("/config/reload",{method:"POST"});state.config=result.config;renderAll();toast("Configuration reloaded from YAML")}catch(error){toast(error.message,"error")}};$("#refresh-button").onclick=bootstrap;
$("#new-benchmark").onclick=()=>openBenchmarkDialog();$("#benchmark-form").onsubmit=saveBenchmark;$("#add-benchmark-target").onclick=()=>addBenchmarkTarget();$("#benchmark-skill-server").onchange=excludeSkillServerFromTaskTools;$("#close-benchmark-dialog").onclick=()=>$("#benchmark-dialog").close();$("#cancel-benchmark-dialog").onclick=()=>$("#benchmark-dialog").close();
bootstrap();
